<template>
  <main class="ai-page"><header class="page-header"><div><p class="eyebrow">WAREHOUSE INTELLIGENCE</p><h1>AI 助手</h1><p>基于数据库中的温湿度、库存与操作记录，生成可执行的仓储建议。</p></div></header>
    <section class="ai-workspace"><section class="chat-panel"><div ref="messageList" class="messages"><div v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="message-mark"><el-icon><component :is="message.role === 'assistant' ? MagicStick : User" /></el-icon></div><div class="message-body"><div class="message-meta">{{ message.role === 'assistant' ? 'AI 助手' : '您' }} <time>{{ message.time }}</time></div><markdown-content :content="message.content" /></div></div><div v-if="sending" class="message assistant"><div class="message-mark"><el-icon><MagicStick /></el-icon></div><div class="message-body typing"><i></i><i></i><i></i></div></div></div><div class="quick-prompts"><span>快速提问</span><button v-for="item in suggestions" :key="item" @click="ask(item)">{{ item }}</button></div><div class="composer"><el-input v-model="input" type="textarea" :rows="3" resize="none" placeholder="输入与仓储数据相关的问题..." :disabled="sending" @keydown.enter.exact.prevent="ask()" /><el-button type="primary" :icon="Promotion" :loading="sending" @click="ask()">发送</el-button></div></section>
      <aside class="data-panel"><div class="aside-heading"><div><h2>实时数据概览</h2><p>来自数据库</p></div><span>{{ dashboard.updatedAt ? formatTime(dashboard.updatedAt) : '--' }}</span></div><div class="metrics"><div><span>平均温度</span><strong>{{ formatMetric(dashboard.averageTemperature, ' C') }}</strong></div><div><span>平均湿度</span><strong>{{ formatMetric(dashboard.averageHumidity, ' %') }}</strong></div><div><span>库存总数量</span><strong>{{ dashboard.totalQuantity ?? '--' }}</strong></div><div><span>物品种类</span><strong>{{ dashboard.productTypes ?? '--' }}</strong></div></div><div class="data-section"><h3><el-icon><DataAnalysis /></el-icon>数据覆盖</h3><p>已读取 {{ dashboard.telemetryRooms ?? 0 }} 个房间的实时温湿度数据。</p></div><div class="data-section"><h3><el-icon><Warning /></el-icon>操作提醒</h3><p>最近 10 条空调操作中有 <b>{{ dashboard.failedOperations ?? 0 }}</b> 条失败记录。</p></div><div class="side-actions"><el-button :icon="Document" @click="ask('请根据当前数据库数据生成一份仓储运营报告')">生成运营报告</el-button><el-button :icon="Delete" @click="clearChat">清空对话</el-button></div></aside>
    </section>
  </main>
</template>

<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { DataAnalysis, Delete, Document, MagicStick, Promotion, User, Warning } from '@element-plus/icons-vue'
import { ElMessage } from 'element-plus'
import axios from '@/store/SetAxios'
import MarkdownContent from '@/components/MarkdownContent.vue'
interface Message { id: number; role: 'assistant' | 'user'; content: string; time: string }
interface Dashboard { averageTemperature: number | null; averageHumidity: number | null; telemetryRooms: number | null; totalQuantity: number | null; productTypes: number | null; failedOperations: number | null; updatedAt?: string }
const sessionId = `warehouse-${Date.now()}`; const input = ref(''); const sending = ref(false); const dashboardLoading = ref(false); const messageList = ref<HTMLElement | null>(null); const suggestions = ref(['分析当前温湿度状态', '汇总当前库存并提示关注项', '分析最近空调操作失败原因', '根据当前数据给出节能建议']); const dashboard = ref<Dashboard>({ averageTemperature: null, averageHumidity: null, telemetryRooms: null, totalQuantity: null, productTypes: null, failedOperations: null }); const messages = ref<Message[]>([{ id: 1, role: 'assistant', content: '您好，我已接入仓储数据库。您可以询问当前温湿度、库存情况或最近的空调操作记录。', time: '现在' }])
const formatTime = (value: string) => new Date(value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }); const formatMetric = (value: number | null, unit: string) => value === null ? '--' : `${value}${unit}`
const scrollToBottom = async () => { await nextTick(); if (messageList.value) messageList.value.scrollTop = messageList.value.scrollHeight }
const loadDashboard = async () => { dashboardLoading.value = true; try { const { data } = await axios.get<Dashboard>('/ai/dashboard'); dashboard.value = data } catch { ElMessage.error('实时数据加载失败') } finally { dashboardLoading.value = false } }
const ask = async (question?: string) => { const content = (question ?? input.value).trim(); if (!content || sending.value) return; messages.value.push({ id: Date.now(), role: 'user', content, time: '刚刚' }); input.value = ''; sending.value = true; await scrollToBottom(); try { const { data } = await axios.post<{ success: boolean; response: string }>('/ai/chat', { message: content, sessionId }); if (!data.success) throw new Error(); messages.value.push({ id: Date.now() + 1, role: 'assistant', content: data.response, time: '刚刚' }); void loadDashboard() } catch (error: any) { const serverMessage = error?.response?.data?.message; const detail = Array.isArray(serverMessage) ? serverMessage.join('；') : (typeof serverMessage === 'string' && serverMessage) ? serverMessage : (error?.response?.status ? `服务端返回 ${error.response.status}` : (error?.message ?? '未知错误')); messages.value.push({ id: Date.now() + 1, role: 'assistant', content: `请求未完成：${detail}`, time: '刚刚' }) } finally { sending.value = false; await scrollToBottom() } }
const clearChat = async () => { try { await axios.delete(`/ai/chat/history/${sessionId}`) } catch { /* Clear local state even when the API is unavailable. */ } messages.value = [{ id: Date.now(), role: 'assistant', content: '对话已清空。当前问题将继续基于数据库实时数据回答。', time: '现在' }]; await scrollToBottom() }
onMounted(() => { void loadDashboard() })
</script>

