nt-size: 14px; line-height: 1.65; }.message.user .message-body { border-color: #2e658a; background: #1f4058; }.message-meta { margin-bottom: 5px; color: #aebbc6; font-size: 12px; }.message-meta time { margin-left: 7px; color: #748391; }.message-body p { margin: 0; white-space: pre-wrap; }.typing { display: flex; gap: 5px; align-items: center; min-width: 48px; }.typing i { width: 6px; height: 6px; border-radius: 50%; background: #83c3ef; animation: pulse 1s infinite alternate; }.typing i:nth-child(2) { animation-delay: .2s; }.typing i:nth-child(3) { animation-delay: .4s; }@keyframes pulse { to { opacity: .25; transform: translateY(-3px); } }.quick-prompts { display: flex; flex-wrap: wrap; gap: 7px; padding: 12px 16px; border-top: 1px solid #414b55; }.quick-prompts > span { align-self: center; margin-right: 3px; color: #8e9ca8; font-size: 12px; }.quick-prompts button { padding: 6px 8px; border: 1px solid #4a5661; border-radius: 5px; background: #292f35; color: #aebbc6; font: inherit; font-size: 12px; cursor: pointer; }.quick-prompts button:hover { border-color: #83c3ef; background: #3a444d; color: #edf3f8; }.composer { display: flex; gap: 10px; padding: 14px 16px; border-top: 1px solid #414b55; background: #292f35; }.composer :deep(.el-textarea__inner) { min-height: 68px !important; background: #252a2f; box-shadow: 0 0 0 1px #4a5661 inset; color: #edf3f8; }.composer .el-button { align-self: flex-end; }.data-panel { padding: 16px; overflow: auto; }.aside-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; padding-bottom: 14px; border-bottom: 1px solid #414b55; }.aside-heading h2 { margin: 0; font-size: 16px; }.aside-heading p { margin: 5px 0 0; color: #8e9ca8; font-size: 12px; }.aside-heading > span { color: #8e9ca8; font-size: 11px; }.metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 14px 0; }.metrics > div { padding: 10px; border: 1px solid #414b55; border-radius: 5px; background: #292f35; }.metrics span, .metrics strong { display: block; }.metrics span { margin-bottom: 5px; color: #8e9ca8; font-size: 11px; }.metrics strong { color: #edf3f8; font-size: 16px; font-weight: 600; }.data-section { padding: 13px 0; border-top: 1px solid #414b55; }.data-section h3 { display: flex; align-items: center; gap: 6px; margin: 0 0 7px; color: #c6d0d9; font-size: 13px; }.data-section h3 .el-icon { color: #83c3ef; }.data-section p { margin: 0; color: #aebbc6; font-size: 12px; line-height: 1.6; }.data-section b { color: #f59b9b; }.side-actions { display: grid; gap: 8px; padding-top: 4px; }.side-actions :deep(.el-button) { justify-content: flex-start; margin: 0; border-color: #4a5661; background: #292f35; color: #c6d0d9; }@media (max-width: 900px) { .ai-page { overflow: auto; }.ai-workspace { grid-template-columns: 1fr; }.chat-panel { min-height: 560px; }.data-panel { min-height: 340px; }.page-header { flex-direction: column; } }@media (max-width: 600px) { .ai-page { padding: 16px 12px; }.quick-prompts > span { width: 100%; }.composer { flex-direction: column; }.composer .el-button { align-self: stretch; }.message { max-width: 95%; } }
.messages::-webkit-scrollbar, .data-panel::-webkit-scrollbar { width: 7px; }
